contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount, uint cashOutAmount) public payable {
        require(address(this).balance >= depositAmount);

        // Read initial observed state.
        uint balBefore = c.balances(address(this));
        uint contractBalBefore = address(c).balance;

        // Create a positive balance owned by this test contract.
        c.Deposit{value: depositAmount}();

        // Current balance after deposit (observable through public getter).
        uint balAfterDeposit = c.balances(address(this));
        uint contractBalAfterDeposit = address(c).balance;

        // The deciding call: try to cash out.
        bool reverted;
        try c.CashOut(cashOutAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = c.balances(address(this));
        uint contractBalAfter = address(c).balance;

        // General rule: if _am is within the balance and the Ether transfer succeeds,
        // both the contract's Ether balance and the caller's recorded balance fall by _am.
        assert(
            reverted
            || cashOutAmount > balAfterDeposit
            || (balAfter == balAfterDeposit - cashOutAmount
                && contractBalAfter == contractBalAfterDeposit - cashOutAmount)
        );
    }

    receive() external payable {}
}

